32	/**
33	 * 遏制逾期并发测试：验证检查、确认与遏制在事件行锁下按事务提交顺序生效——
34	 * 遏制先提交不再新增升级；确认与遏制竞争时升级状态不可回退，不能在取消后补确认。
35	 * 使用可控 Clock 将事件置于已逾期状态，不依赖真实睡眠。
36	 */
37	@SpringBootTest
38	@Import(ControllableClock.Config.class)
39	class EscalationConcurrencyTest {
40	
41	    private static final Instant T0 = Instant.parse("2026-09-22T00:00:00Z");
42	
43	    @Autowired
44	    private IncidentService service;
45	
46	    @Autowired
47	    private JdbcTemplate jdbc;
48	
49	    @Autowired
50	    private Clock clock;
51	
52	    @BeforeEach
53	    void clean() {
54	        jdbc.update("DELETE FROM command_keys");
55	        jdbc.update("DELETE FROM incident_escalations");
56	        jdbc.update("DELETE FROM incident_status_history");
57	        jdbc.update("DELETE FROM incident_transfers");
58	        jdbc.update("DELETE FROM incident_actions");
59	        jdbc.update("DELETE FROM incident_task_blockers");
60	        jdbc.update("DELETE FROM incident_tasks");
61	        jdbc.update("DELETE FROM incidents");
62	        ((ControllableClock) clock).setInstant(T0);
63	    }
64	
65	    private static String key() {
66	        return "CMD-" + UUID.randomUUID();
67	    }
68	
69	    private void overdueCommanding(String incidentKey) {
70	        service.report(new ReportRequest(incidentKey, "S1", "并发逾期", "r"));
71	        service.takeover(incidentKey, "alice", new TakeoverRequest(key()));
72	        ((ControllableClock) clock).setInstant(T0.plus(10, ChronoUnit.MINUTES));
73	    }
74	
75	    private static <T> List<Object> runConcurrently(List<Callable<T>> tasks) throws Exception {
76	        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
77	        try {
78	            CountDownLatch ready = new CountDownLatch(tasks.size());
79	            CountDownLatch start = new CountDownLatch(1);
80	            List<Future<Object>> futures = new ArrayList<>();
81	            for (Callable<T> task : tasks) {
82	                futures.add(pool.submit(() -> {
83	                    ready.countDown();
84	                    start.await(5, TimeUnit.SECONDS);
85	                    try {
86	                        return task.call();
87	                    } catch (Exception e) {
88	                        return e;
89	                    }
90	                }));
91	            }
92	            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
93	            start.countDown();
94	            List<Object> results = new ArrayList<>();
95	            for (Future<Object> future : futures) {
96	                results.add(future.get(30, TimeUnit.SECONDS));
97	            }
98	            return results;
99	        } finally {
100	            pool.shutdownNow();
101	        }
102	    }
