104	    @Test
105	    void concurrentCheckAndContain_commitOrderWins_noOpenLingers() throws Exception {
106	        for (int round = 0; round < 5; round++) {
107	            String ik = "INC-C-" + round;
108	            overdueCommanding(ik);
109	            List<Object> results = runConcurrently(List.of(
110	                    () -> service.checkEscalation(ik, new EscalationCheckRequest(key())),
111	                    () -> service.changeStatus(ik, "alice", new StatusRequest(key(), "CONTAINED"))));
112	            long failures = results.stream().filter(ApiException.class::isInstance).count();
113	            // 两个操作语义上都可能成功（检查在非 COMMANDING 时是空结果成功），但结果必须自洽
114	            assertThat(failures).isZero();
115	
116	            IncidentView end = service.get(ik);
117	            List<EscalationView> escalations = service.history(ik).escalations();
118	            if ("CONTAINED".equals(end.status()) && escalations.isEmpty()) {
119	                // 遏制先提交：检查不再新增升级
120	                continue;
121	            }
122	            // 检查先提交：恰好一条记录，且被同事务/随后的遏制取消，绝不残留 OPEN
123	            assertThat(end.status()).isEqualTo("CONTAINED");
124	            assertThat(escalations).hasSize(1);
125	            assertThat(escalations.get(0).status()).isEqualTo("CANCELLED");
126	        }
127	    }
