package com.example.starter.incident;

/**
 * 升级阶梯等级变更类型：ESCALATE 升级（分数达阈值自动提升，可跨级）；
 * DEESCALATE 降级（逐级，需不同指挥员确认且冷却已过）。
 */
public enum LadderChangeType {

    /** 升级：分数达到更高阈值时自动提升，允许跨级。 */
    ESCALATE,

    /** 降级：必须由不同指挥员确认，逐级下降且冷却已过。 */
    DEESCALATE;
}

package com.example.starter.incident;

import java.time.Instant;
import java.util.List;

/**
 * 升级阶梯阈值配置实体，对应 incident_ladder_configs 表，版本化追加、旧版本不回写。
 * thresholds 为 1~5 级进入阈值（含），必须严格递增；等级区间左闭右开，
 * 即 k 级覆盖分数区间 [thresholds[k-1], thresholds[k])，5 级覆盖 [thresholds[4], ∞)。
 * cooldownMinutes 为降级冷却分钟数（1~10080），冷却区间 [冷却起点, 起点+冷却分钟数) 左闭右开。
 */
public record LadderConfig(
        long id,
        int configVersion,
        List<Integer> thresholds,
        int cooldownMinutes,
        String createdBy,
        Instant createdAt) {

    /** 阶梯级数（1~5 级，对应 5 个阈值）。 */
    public static final int LEVEL_COUNT = 5;

    public LadderConfig {
        thresholds = List.copyOf(thresholds);
        if (thresholds.size() != LEVEL_COUNT) {
            throw new IllegalArgumentException("阈值必须恰好 " + LEVEL_COUNT + " 个");
        }
    }

    /**
     * 计算分数所在等级：满足 score >= thresholds[k] 的最高级（区间左闭右开）；
     * 未达 1 级阈值返回 0（未入阶梯）。
     */
    public int levelFor(int score) {
        int level = 0;
        for (Integer threshold : thresholds) {
            if (score >= threshold) {
                level++;
            } else {
                break;
            }
        }
        return level;
    }

    /**
     * 进入下一等级所需的阈值（要求值）；已在最高级返回 null。
     */
    public Integer nextThreshold(int currentLevel) {
        return currentLevel >= LEVEL_COUNT ? null : thresholds.get(currentLevel);
    }
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 事件升级阶梯当前状态实体，对应 incident_ladder_states 表，每事件至多一条。
 * currentLevel 为当前等级 0~5（0 表示未达 1 级阈值）；
 * cooldownStartAt 为冷却起点 UTC：最近一次等级变更（升级或降级）时刻，尚无变更时为首次评分时刻；
 * lastOperator 为最近一次等级变更操作人，降级必须由与其不同的指挥员确认。
 */
public record LadderState(
        long id,
        long incidentId,
        int riskScore,
        int currentLevel,
        int configVersion,
        Instant cooldownStartAt,
        String lastOperator,
        Instant createdAt,
        Instant updatedAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 升级阶梯等级变更历史实体，对应 incident_ladder_history 表，只追加不回写。
 * riskScore/configVersion/actor/occurredAt 均为变更时快照；
 * 后续配置修订不回写历史记录。
 */
public record LadderHistoryEntry(
        long id,
        long incidentId,
        LadderChangeType changeType,
        int fromLevel,
        int toLevel,
        int riskScore,
        int configVersion,
        String actor,
        Instant occurredAt,
        Instant createdAt) {
}

